"153 :   @Override
154 :   public void visit(NodeTraversal t, Node n, Node parent) {
155 :     if (!n.isName()) {
156 :       return;
157 :     }
158 : 
159 :     String varName = n.getString();
160 : 
161 :     // Only a function can have an empty name.
162 :     if (varName.isEmpty()) {
163 :       Preconditions.checkState(parent.isFunction());
164 :       Preconditions.checkState(NodeUtil.isFunctionExpression(parent));
165 :       return;
166 :     }
167 : 
168 :     // Check if this is a declaration for a var that has been declared
169 :     // elsewhere. If so, mark it as a duplicate.
170 :     if ((parent.isVar() ||
171 :          NodeUtil.isFunctionDeclaration(parent)) &&
172 :         varsToDeclareInExterns.contains(varName)) {
173 :       createSynthesizedExternVar(varName);
174 : 
175 :       n.addSuppression("duplicate");
176 :     }
177 : 
178 :     // Check that the var has been declared.
179 :     Scope scope = t.getScope();
180 :     Scope.Var var = scope.getVar(varName);
181 :     if (var == null) {
182 :       if (NodeUtil.isFunctionExpression(parent)) {
183 :         // e.g. [ function foo() {} ], it's okay if "foo" isn't defined in the
184 :         // current scope.
185 :       } else if (!(scope.isLocal() && ARGUMENTS.equals(varName))) {
186 :         // The extern checks are stricter, don't report a second error.
187 :         if (!strictExternCheck || !t.getInput().isExtern()) {
188 :           t.report(n, UNDEFINED_VAR_ERROR, varName);
189 :         }
190 : 
191 :         if (sanityCheck) {
192 :           throw new IllegalStateException("Unexpected variable " + varName);
193 :         } else {
194 :           createSynthesizedExternVar(varName);
195 :           scope.getGlobalScope().declare(varName, n,
196 :               null, compiler.getSynthesizedExternsInput());
197 :         }
198 :       }
199 :       return;
200 :     }
201 : 
202 :     CompilerInput currInput = t.getInput();
203 :     CompilerInput varInput = var.input;
204 :     if (currInput == varInput || currInput == null || varInput == null) {
205 :       // The variable was defined in the same file. This is fine.
206 :       return;
207 :     }
208 : 
209 :     // Check module dependencies.
210 :     JSModule currModule = currInput.getModule();
211 :     JSModule varModule = varInput.getModule();
212 :     JSModuleGraph moduleGraph = compiler.getModuleGraph();
213 :     if (!sanityCheck &&
214 :         varModule != currModule && varModule != null && currModule != null) {
215 :       if (moduleGraph.dependsOn(currModule, varModule)) {
216 :         // The module dependency was properly declared.
217 :       } else {
218 :         if (scope.isGlobal()) {
219 :           if (moduleGraph.dependsOn(varModule, currModule)) {
220 :             // The variable reference violates a declared module dependency.
221 :             t.report(n, VIOLATED_MODULE_DEP_ERROR,
222 :                      currModule.getName(), varModule.getName(), varName);
223 :           } else {
224 :             // The variable reference is between two modules that have no
225 :             // dependency relationship. This should probably be considered an
226 :             // error, but just issue a warning for now.
227 :             t.report(n, MISSING_MODULE_DEP_ERROR,
228 :                      currModule.getName(), varModule.getName(), varName);
229 :           }
230 :         } else {
231 :           t.report(n, STRICT_MODULE_DEP_ERROR,
232 :                    currModule.getName(), varModule.getName(), varName);
233 :         }
234 :       }
235 :     }
236 :   }"

