"201 :   @Override
202 :   public void visit(NodeTraversal t, Node n, Node parent) {
203 :     switch (n.getType()) {
204 :       case Token.CALL:
205 :         boolean isExpr = parent.isExprResult();
206 :         Node left = n.getFirstChild();
207 :         if (left.isGetProp()) {
208 :           Node name = left.getFirstChild();
209 :           if (name.isName() &&
210 :               GOOG.equals(name.getString())) {
211 :             // For the sake of simplicity, we report code changes
212 :             // when we see a provides/requires, and don't worry about
213 :             // reporting the change when we actually do the replacement.
214 :             String methodName = name.getNext().getString();
215 :             if ("base".equals(methodName)) {
216 :               processBaseClassCall(t, n);
217 :             } else if (!isExpr) {
218 :               // All other methods must be called in an EXPR.
219 :               break;
220 :             } else if ("define".equals(methodName)) {
221 :               processDefineCall(t, n, parent);
222 :             } else if ("require".equals(methodName)) {
223 :               processRequireCall(t, n, parent);
224 :             } else if ("provide".equals(methodName)) {
225 :               processProvideCall(t, n, parent);
226 :             } else if ("exportSymbol".equals(methodName)) {
227 :               Node arg = left.getNext();
228 :               if (arg.isString()) {
229 :                 int dot = arg.getString().indexOf('.');
230 :                 if (dot == -1) {
231 :                   exportedVariables.add(arg.getString());
232 :                 } else {
233 :                   exportedVariables.add(arg.getString().substring(0, dot));
234 :                 }
235 :               }
236 :             } else if ("addDependency".equals(methodName)) {
237 :               CodingConvention convention = compiler.getCodingConvention();
238 :               List<String> typeDecls =
239 :                   convention.identifyTypeDeclarationCall(n);
240 :               if (typeDecls != null) {
241 :                 for (String typeDecl : typeDecls) {
242 :                   compiler.getTypeRegistry().forwardDeclareType(typeDecl);
243 :                 }
244 :               }
245 : 
246 :               // We can't modify parent, so just create a node that will
247 :               // get compiled out.
248 :               parent.replaceChild(n, IR.number(0));
249 :               compiler.reportCodeChange();
250 :             } else if ("setCssNameMapping".equals(methodName)) {
251 :               processSetCssNameMapping(t, n, parent);
252 :             }
253 :           }
254 :         }
255 :         break;
256 : 
257 :       case Token.ASSIGN:
258 :       case Token.NAME:
259 :         // If this is an assignment to a provided name, remove the provided
260 :         // object.
261 :         handleCandidateProvideDefinition(t, n, parent);
262 :         break;
263 : 
264 :       case Token.EXPR_RESULT:
265 :         handleTypedefDefinition(t, n);
266 :         break;
267 : 
268 :       case Token.FUNCTION:
269 :         // If this is a declaration of a provided named function, this is an
270 :         // error. Hoisted functions will explode if they're provided.
271 :         if (t.inGlobalScope() &&
272 :             !NodeUtil.isFunctionExpression(n)) {
273 :           String name = n.getFirstChild().getString();
274 :           ProvidedName pn = providedNames.get(name);
275 :           if (pn != null) {
276 :             compiler.report(t.makeError(n, FUNCTION_NAMESPACE_ERROR, name));
277 :           }
278 :         }
279 :         break;
280 : 
281 :       case Token.GETPROP:
282 :         if (n.getFirstChild().isName() &&
283 :             !parent.isCall() &&
284 :             !parent.isAssign() &&
285 :             "goog.base".equals(n.getQualifiedName())) {
286 :           reportBadBaseClassUse(t, n, "May only be called directly.");
287 :         }
288 :         break;
289 :     }
290 :   }"

"242 :   private void createSynthesizedExternVar(String varName) {
243 :     Node nameNode = IR.name(varName);
244 : 
245 :     // Mark the variable as constant if it matches the coding convention
246 :     // for constant vars.
247 :     // NOTE(nicksantos): honestly, I'm not sure how much this matters.
248 :     // AFAIK, all people who use the CONST coding convention also
249 :     // compile with undeclaredVars as errors. We have some test
250 :     // cases for this configuration though, and it makes them happier.
251 :     if (compiler.getCodingConvention().isConstant(varName)) {
252 :       nameNode.putBooleanProp(Node.IS_CONSTANT_NAME, true);
253 :     }
254 : 
255 :     getSynthesizedExternsRoot().addChildToBack(
256 :         IR.var(nameNode));
257 :     varsToDeclareInExterns.remove(varName);
258 :     compiler.reportCodeChange();
259 :   }"

"403 :   private void handleCandidateProvideDefinition(
404 :       NodeTraversal t, Node n, Node parent) {
405 :     if (t.inGlobalScope()) {
406 :       String name = null;
407 :       if (n.isName() && parent.isVar()) {
408 :         name = n.getString();
409 :       } else if (n.isAssign() &&
410 :           parent.isExprResult()) {
411 :         name = n.getFirstChild().getQualifiedName();
412 :       }
413 : 
414 :       if (name != null) {
415 :         if (parent.getBooleanProp(Node.IS_NAMESPACE)) {
416 :           processProvideFromPreviousPass(t, name, parent);
417 :         } else {
418 :           ProvidedName pn = providedNames.get(name);
419 :           if (pn != null) {
420 :             pn.addDefinition(parent, t.getModule());
421 :           }
422 :         }
423 :       }
424 :     }
425 :   }"

